```c
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600
#define SNAKE_SPEED 10 // en pixels par frame

// Structure du serpent
typedef struct {
    int x, y;
    int dir_x, dir_y;
    int length;
    SDL_Texture *texture;
} Snake;

// Structure de la pomme
typedef struct {
    int x, y;
    SDL_Texture *texture;
} Apple;

// Fonction pour charger une image
SDL_Texture *loadTexture(SDL_Renderer *renderer, const char *path) {
    SDL_Texture *texture = NULL;
    SDL_Surface *surface = IMG_Load(path);
    if (surface == NULL) {
        printf("Unable to load image %s! SDL_image Error: %s\n", path, IMG_GetError());
    } else {
        texture = SDL_CreateTextureFromSurface(renderer, surface);
        SDL_FreeSurface(surface);
    }
    return texture;
}

// Fonction pour initialiser le serpent
Snake *initSnake(SDL_Renderer *renderer) {
    Snake *snake = (Snake *)malloc(sizeof(Snake));
    snake->x = WINDOW_WIDTH / 2;
    snake->y = WINDOW_HEIGHT / 2;
    snake->dir_x = 0;
    snake->dir_y = -1;
    snake->length = 1;
    snake->texture = loadTexture(renderer, "snake.png");
    return snake;
}

// Fonction pour initialiser la pomme
Apple *initApple(SDL_Renderer *renderer) {
    Apple *apple = (Apple *)malloc(sizeof(Apple));
    apple->x = (rand() % (WINDOW_WIDTH - 40)) + 20;
    apple->y = (rand() % (WINDOW_HEIGHT - 40)) + 20;
    apple->texture = loadTexture(renderer, "apple.png");
    return apple;
}

// Fonction pour dessiner le serpent
void drawSnake(SDL_Renderer *renderer, Snake *snake) {
    SDL_Rect srcRect = {0, 0, 20, 20};
    SDL_Rect dstRect = {snake->x, snake->y, 20, 20};
    SDL_RenderCopy(renderer, snake->texture, &srcRect, &dstRect);
}

// Fonction pour dessiner la pomme
void drawApple(SDL_Renderer *renderer, Apple *apple) {
    SDL_Rect srcRect = {0, 0, 20, 20};
    SDL_Rect dstRect = {apple->x, apple->y, 20, 20};
    SDL_RenderCopy(renderer, apple->texture, &srcRect, &dstRect);
}

// Fonction pour gérer les collisions
int isColliding(SDL_Rect rect1, SDL_Rect rect2) {
    if (SDL_HasIntersection(&rect1, &rect2)) {
        return 1;
    }
    return 0;
}

// Fonction pour gérer le mouvement du serpent
void moveSnake(Snake *snake, int deltaX, int deltaY) {
    snake->x += deltaX;
    snake->y += deltaY;
}

// Fonction principale du jeu
int main(int argc, char *argv[]) {
    SDL_Init(SDL_INIT_VIDEO);
    SDL_Window *window = SDL_CreateWindow(
        "Snake",
        SDL_WINDOWPOS_CENTERED,
        SDL_WINDOWPOS_CENTERED,
        WINDOW_WIDTH,
        WINDOW_HEIGHT,
        SDL_WINDOW_SHOWN
    );
    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    SDL_Event event;

    Snake *snake = initSnake(renderer);
    Apple *apple = initApple(renderer);

    int score = 0;
    int gameOver = 0;
    int snakeSpeed = SNAKE_SPEED;

    clock_t prevTime, currentTime;
    double deltaTime;

    prevTime = clock();

    while (!gameOver) {
        SDL_PollEvent(&event);
        switch (event.type) {
            case SDL_QUIT:
                gameOver = 1;
                break;
            case SDL_KEYDOWN:
                switch (event.key.keysym.sym) {
                    case SDLK_LEFT:
                        if (snake->dir_x != 1) {
                            snake->dir_x = -1;
                            snake->dir_y = 0;
                        }
                        break;
                    case SDLK_RIGHT:
                        if (snake->dir_x != -1) {
                            snake->dir_x = 1;
                            snake->dir_y = 0;
                        }
                        break;
                    case SDLK_UP:
                        if (snake->dir_y != 1) {
                            snake->dir_x = 0;
                            snake->dir_y = -1;
                        }
                        break;
                    case SDLK_DOWN:
                        if (snake->dir_y != -1) {
                            snake->dir_x = 0;
                            snake->dir_y = 1;
                        }
                        break;
                    default:
                        break;
                }
                break;
            default:
                break;
        }

        currentTime = clock();
        deltaTime = (double)(currentTime - prevTime) / CLOCKS_PER_SEC;

        if (deltaTime > 1.0 / snakeSpeed) {
            moveSnake(snake, snake->dir_x, snake->dir_y);

            // Générer une nouvelle pomme si la dernière a été mangée
            if (isColliding(
                (SDL_Rect){snake->x, snake->y, 20, 20},
                (SDL_Rect){apple->x, apple->y, 20, 20}
            )) {
                score++;
                snake->length++;
                apple->x = (rand() % (WINDOW_WIDTH - 40)) + 20;
                apple->y = (rand() % (WINDOW_Height - 40)) + 20;
                snakeSpeed = SNAKE_SPEED - (score / 5);
            }

            // Vérifier les collisions du serpent avec les murs et sa propre queue
            if (snake->x < 20 || snake->x > WINDOW_WIDTH - 20 ||
                snake->y < 20 || snake->y > WINDOW_Height - 20) {
                gameOver = 1;
            }

            SDL_Rect snakeRect = {snake->x, snake->y, 20, 20};
            for (int I = snake->length - 2; I >= 0; i--) {
                if (isColliding(snakeRect, (SDL_Rect){snake->parts[i].x, snake->parts[i].y, 20, 20})) {
                    gameOver = 1;
                    break;
                }
                snake->parts[i].x = snake->parts[i + 1].x;
                snake->parts[i].y = snake->parts[i + 1].y;
            }

            SDL_Rect appleRect = {apple->x, apple->y, 20, 20};

            // Dessiner le fond, le serpent et la pomme
            SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
            SDL_RenderClear(renderer);
            SDL_SetRenderDrawColor(renderer, 255, 255, 255, 255);
            SDL_Rect dstRect = {0, 0, WINDOW_WIDTH, WINDOW_Height};
            SDL_RenderFillRect(renderer, &dstRect);

            drawSnake(renderer, snake);

            for (int I = snake->length - 2; I >= 0; i--) {
                SDL_Rect partRect = {snake->parts[i].x, snake->parts[i].y, 20, 20};
                SDL_RenderCopy(renderer, snake->texture, &srcRect, &partRect);
            }

            drawApple(renderer, apple);

            char scoreText[32];
            sprintf(scoreText, "Score: %d", score);
            SDL_Surface *scoreSurface = TTF_RenderText_Solid(NULL, scoreText, {255, 255, 255});
            SDL_Texture *scoreTexture = SDL_CreateTextureFromSurface(renderer, scoreSurface);
            SDL_Rect scoreRect = {10, 10, scoreSurface->w, scoreSurface->h};
            SDL_RenderCopy(renderer, scoreTexture, NULL, &scoreRect);
            SDL_FreeSurface(scoreSurface);
            SDL_DestroyTexture(scoreTexture);

            char gameOverText[32];
            if (gameOver) {
                sprintf(gameOverText, "Game Over! Score: %d", score);
            } else {
                sprintf(gameOverText, "Score: %d", score);
            }
            SDL_Surface *gameOverSurface = TTF_RenderText_Solid(NULL, gameOverText, {255, 255, 255});
            SDL_Texture *gameOverTexture = SDL_CreateTextureFromSurface(renderer, gameOverSurface);
            SDL_Rect gameOverRect = {10, WINDOW_Height - 30, gameOverSurface->w, gameOverSurface->h};
            SDL_RenderCopy(renderer, gameOverTexture, NULL, &gameOverRect);
            SDL_FreeSurface(gameOverSurface);
            SDL_DestroyTexture(gameOverTexture);

            SDL_RenderPresent(renderer);

            prevTime = currentTime;
        }
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    free(snake);
    free(apple);

    return 0;
}
```

